let Some(mut send) = Send::find_by_access_id(access_id, &conn).await else { err_code!(SEND_INACCESSIBLE_MSG, 404) };
if let Some(max_access_count) = send.max_access_count && send.access_count >= max_access_count { err_code!(SEND_INACCESSIBLE_MSG, 404) }
if !send.is_accessible() { err_code!(SEND_INACCESSIBLE_MSG, 404) }
if send.password_hash.is_some() { match ... Some(ref p) if send.check_password(p) => {}, Some(_)=>err!("Invalid password"), None=>err_code!("Password not provided",401) } }

if email == grantor_user.email { err!("You can not set yourself as an emergency contact.") }
let (grantee_user, new_user) = match User::find_by_mail(&email, &conn).await { None => { ...user.save(...); (user,true) }, Some(user)=>... };
let mut new_emergency_access = EmergencyAccess::new(grantor_user.uuid, grantee_user.email, Invited, new_type, wait_time_days);
new_emergency_access.save(&conn).await?;

async fn delete_emergency_access(emer_id: EmergencyAccessId, headers: Headers, conn: DbConn) -> EmptyResult {
  check_emergency_access_enabled()?;
  let emergency_access = match (EmergencyAccess::find_by_uuid_and_grantor_uuid(&emer_id, &headers.user.uuid, &conn).await, EmergencyAccess::find_by_uuid_and_grantee_uuid(&emer_id, &headers.user.uuid, &conn).await) {
    (Some(grantor_emer), None) => grantor_emer, (None, Some(grantee_emer)) => grantee_emer,
    _ => err!("Emergency access not valid.") };
  emergency_access.delete(&conn).await?; }

let claims = decode_emergency_access_invite(token)?;
if claims.email != headers.user.email { err!("Claim email does not match") }
emergency_access.accept_invite(&grantee_user.uuid, &grantee_user.email, &conn).await?;

if emergency_access.status != EmergencyAccessStatus::Accepted as i32 || ... { err!("Emergency access not valid.") }
emergency_access.status = EmergencyAccessStatus::Confirmed as i32;
emergency_access.key_encrypted = Some(key); emergency_access.email = None; emergency_access.save(&conn).await?;

if emergency_access.status != EmergencyAccessStatus::Confirmed as i32 { err!("Emergency access not valid.") }
emergency_access.status = EmergencyAccessStatus::RecoveryInitiated as i32;
emergency_access.recovery_initiated_at = Some(now); emergency_access.last_notification_at = Some(now); emergency_access.save(&conn).await?;

async fn reject_emergency_access(emer_id: EmergencyAccessId, headers: Headers, conn: DbConn) -> JsonResult {
  let Some(mut emergency_access) = EmergencyAccess::find_by_uuid_and_grantor_uuid(&emer_id, &headers.user.uuid, &conn).await else { err!("Emergency access not valid.") };
  if emergency_access.status != EmergencyAccessStatus::RecoveryInitiated as i32 && emergency_access.status != EmergencyAccessStatus::RecoveryApproved as i32 { err!("Emergency access not valid.") }
  emergency_access.status = EmergencyAccessStatus::Confirmed as i32;
  emergency_access.save(&conn).await?; ... }

async fn view_emergency_access(emer_id: EmergencyAccessId, headers: Headers, conn: DbConn) -> JsonResult {
  let Some(emergency_access) = EmergencyAccess::find_by_uuid_and_grantee_uuid(&emer_id, &headers.user.uuid, &conn).await else { err!("Emergency access not valid.") };
  if !is_valid_request(&emergency_access, &headers.user.uuid, EmergencyAccessType::View) { err!("Emergency access not valid.") }
  let ciphers = Cipher::find_owned_by_user(&emergency_access.grantor_uuid, &conn).await;
  Ok(Json(json!({ "ciphers": ciphers_json, "keyEncrypted": &emergency_access.key_encrypted, ... }))) }
